MERGE Org.Person T
USING (SELECT * FROM @PersonStaging) S ON T.Email = S.Email
WHEN MATCHED AND (
    T.AddressID <> S.AddressID
    OR T.FirstName <> S.FirstName
    OR T.LastName <> S.LastName
    OR T.Phone <> S.Phone
) THEN
    UPDATE SET FirstName = S.FirstName, LastName = S.LastName, Phone = S.Phone
WHEN NOT MATCHED THEN
    INSERT([AddressID], [FirstName], [LastName], [Email], [Phone])
    VALUES(S.AddressID, S.FirstName, S.LastName, S.Email, S.Phone);
